# Purpose: Summarize independent fixed and estimated spatial GLM comparisons.
# Inputs: tests/fixtures/spglm_reference.json, generated by generate_spglm_reference.R.
# Outputs: tests/fixtures/spglm_comparison.json and tests/spglm_comparison.md.
# Research log: 003_geopytorch_spglm_implementation.tex.
import json
from pathlib import Path

import gpytorch
import numpy as np
import torch

from geopytorch import GLM_FAMILIES, SpatialGeneralizedLinearModel

torch.set_num_threads(1)
folder = Path(__file__).parent / "fixtures"
reference = json.loads((folder / "spglm_reference.json").read_text())


def error(actual, expected):
    return float(np.max(np.abs(np.asarray(actual) - expected)))


def fit_case(case, **options):
    return SpatialGeneralizedLinearModel(case["family"], case["covariance_model"]).fit(
        reference["coords"],
        case["y"],
        reference["design"],
        trials=case["trials"],
        offset=reference["offset"],
        initial=case["initial"],
        dispersion=case["dispersion"],
        likelihood_method=case["method"],
        **options,
    )


def compare_fit(fit, case):
    loglik = (
        fit.log_likelihood_
        if case["method"] == "ml"
        else fit.restricted_log_likelihood_
    )
    return {
        "family": case["family"],
        "method": case["method"],
        "converged": fit.converged_,
        "coefficient_max_error": error(fit.coef_, case["coefficients"]),
        "covariance_max_error": error(fit.coef_covariance_, case["vcov"]),
        "log_likelihood_error": loglik.item() - case["log_likelihood"],
    }


fixed = []
for case in reference["fits"]:
    fit = fit_case(case, training_iterations=0)
    result = compare_fit(fit, case)
    result["covariance_model"] = case["covariance_model"]
    for scale in ("link", "response"):
        prediction = fit.predict(
            reference["newcoords"],
            reference["newdesign"],
            offset=reference["newoffset"],
            type=scale,
            trials=reference["newtrials"] if case["family"] == "binomial" else None,
        )
        result[f"prediction_{scale}_max_error"] = error(
            prediction.mean, case[f"prediction_{scale}"]
        )
        result[f"variance_{scale}_max_error"] = error(
            prediction.variance, case[f"variance_{scale}"]
        )
    fixed.append(result)

estimated = []
for case in reference["estimated"]:
    fit = fit_case(case, fixed=[False, True, True], training_iterations=300)
    result = compare_fit(fit, case)
    result.update(
        parameters=fit.covariance_parameters_.tolist(),
        dispersion=fit.dispersion_.item(),
        reference_parameters=case["parameters"],
        reference_dispersion=case["estimated_dispersion"],
        diagnostics=fit.optimizer_results_,
    )
    estimated.append(result)

dispersion_only = []
for case in reference["dispersion_fits"]:
    fit = fit_case(case, fixed=[True, True, True], training_iterations=150)
    result = compare_fit(fit, case)
    result.update(
        dispersion=fit.dispersion_.item(),
        reference_dispersion=case["estimated_dispersion"],
        reference_optimizer=case["reference_optimizer"],
    )
    dispersion_only.append(result)

report = {
    "spmodel": reference["version"],
    "gpytorch": gpytorch.__version__,
    "torch": torch.__version__,
    "fixed": fixed,
    "estimated": estimated,
    "dispersion_only": dispersion_only,
}
(folder / "spglm_comparison.json").write_text(json.dumps(report, indent=2) + "\n")
lines = [
    "# Spatial GLM comparison",
    "",
    f"CPU float64; spmodel {reference['version']}, GPyTorch {gpytorch.__version__}, PyTorch {torch.__version__}.",
    "",
    (
        "Regenerate from the project root with `Rscript tests/generate_spglm_reference.R` and "
        "`PYTHONPATH=src python tests/compare_spglm.py`. The R generator requires spmodel and jsonlite. "
        "The Python tests use the saved reference fixture and do not require R."
    ),
    "",
    (
        "The 60 fixed-parameter cases cover six families, five existing covariance models, and ML/REML. "
        "They include offsets, nonconstant binomial totals, coefficient covariance, predictions, and delta-method variances. "
        "Reference calls use `local = FALSE`, `diagtol = 0`, and `delta = TRUE` for response uncertainty. "
        "Matérn smoothness is 1.5; the reference range is sqrt(3) times phi."
    ),
    "",
    "Maximum absolute errors across fixed-parameter cases:",
    "",
    "| Family | Coefficients | Coefficient covariance | Log likelihood | Prediction means | Prediction variances |",
    "|---|---:|---:|---:|---:|---:|",
]
for family in GLM_FAMILIES:
    rows = [row for row in fixed if row["family"] == family]
    metrics = [
        max(abs(row[key]) for row in rows)
        for key in (
            "coefficient_max_error",
            "covariance_max_error",
            "log_likelihood_error",
        )
    ]
    for kind in ("prediction", "variance"):
        metrics.append(
            max(
                row[f"{kind}_{scale}_max_error"]
                for row in rows
                for scale in ("link", "response")
            )
        )
    lines.append(
        f"| {family} | " + " | ".join(f"{value:.3g}" for value in metrics) + " |"
    )
lines += [
    "",
    (
        "Twelve further cases estimate partial sill and dispersion with range and nugget fixed. "
        "Several reach zero-sill or infinite-dispersion limits. Maximum coefficient and log-likelihood errors are "
        f"{max(row['coefficient_max_error'] for row in estimated):.3g} and "
        f"{max(abs(row['log_likelihood_error']) for row in estimated):.3g}, respectively. "
        "At infinite dispersion, the inverse dispersion and fitted results are useful comparisons; raw dispersion estimates differ."
    ),
    "",
    (
        "The beta REML boundary case retains a finite iterate but reports nonconvergence when the mode score "
        "loses numerical precision. The reference reaches its dispersion cap of 1e8. "
        "A separate exploratory fit with all covariance parameters free also drives beta dispersion above 4e7; "
        "see `zscratch/inspect_glm_fit.py`. These are small examples, not evidence of universal optimizer reliability."
    ),
    "",
    "Eight cases estimate only dispersion with fixed covariance and have finite interior optima:",
    "",
    "| Family | Method | GeoPyTorch dispersion | Reference dispersion |",
    "|---|---|---:|---:|",
]
for row in dispersion_only:
    lines.append(
        f"| {row['family']} | {row['method']} | {row['dispersion']:.6g} | {row['reference_dispersion']:.6g} |"
    )
lines += [
    "",
    (
        "For the dispersion-only inverse-Gaussian examples, direct reference optimization failed with a "
        "convergence error. The generator instead uses R's `optimize()` over log dispersion in log([0.5, 20]), "
        "evaluating the fixed-parameter `spmodel::spglm()` likelihood. This fallback is recorded in the fixture. "
        "The other dispersion-only references use the package's own optimizer."
    ),
    "",
    (
        "Prediction means use the inverse link at the predicted latent mean. Response variances use the delta "
        "method; they are not integrated posterior moments. Covariance and dispersion estimation uncertainty "
        "is excluded. The comparison retains the reference profile-Laplace normalizing constant. "
        "No grouped random effects, partition factors, anisotropy, or local approximation are tested."
    ),
    "",
]
(folder.parent / "spglm_comparison.md").write_text("\n".join(lines))
print("Compared 60 fixed fits, 12 estimated fits, and 8 dispersion-only fits.")
